import { readFileSync, writeFileSync, renameSync } from 'node:fs';

const file = process.env.NOTES_FILE || 'notes.json';

function load() {
  try {
    return JSON.parse(readFileSync(file, 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
}

function save() {
  const tmp = `${file}.tmp`;
  writeFileSync(tmp, JSON.stringify(notes, null, 2));
  renameSync(tmp, file);
}

const notes = load();
let nextId = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;
export const listNotes = () => notes;
export function addNote(text) { const n = { id: nextId++, text, createdAt: new Date().toISOString() }; notes.push(n); save(); return n; }
export function deleteNote(id) { const i = notes.findIndex((n) => n.id === id); if (i < 0) return false; notes.splice(i, 1); save(); return true; }
EOF
cat > test/store.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const file = join(mkdtempSync(join(tmpdir(), 'notes-')), 'notes.json');
process.env.NOTES_FILE = file;
const { addNote, listNotes, deleteNote } = await import('../src/store.js');

test('add and delete', () => { const n = addNote('hi'); assert.equal(listNotes().length, 1); assert.ok(deleteNote(n.id)); assert.equal(listNotes().length, 0); });

test('persists to file and reloads', async () => {
  const n = addNote('keep me');
  assert.equal(JSON.parse(readFileSync(file, 'utf8'))[0].text, 'keep me');
  const again = await import('../src/store.js?reload');
  assert.equal(again.listNotes()[0].text, 'keep me');
  assert.ok(again.addNote('next').id > n.id);
});
EOF
